package org.springframework.samples.petclinic.owner;

import java.util.List;
import java.util.Optional;

import org.springframework.http.HttpStatus;
import org.springframework.http.ResponseEntity;
import org.springframework.web.bind.annotation.GetMapping;
import org.springframework.web.bind.annotation.PathVariable;
import org.springframework.web.bind.annotation.PostMapping;
import org.springframework.web.bind.annotation.RequestBody;
import org.springframework.web.bind.annotation.RequestMapping;
import org.springframework.web.bind.annotation.RestController;

import jakarta.validation.Valid;

/**
 * REST controller for managing weight records.
 */
@RestController
@RequestMapping("/owners/{ownerId}/pets/{petId}/weight")
class WeightRecordController {

	private final WeightRecordRepository weightRecords;

	private final OwnerRepository owners;

	public WeightRecordController(WeightRecordRepository weightRecords, OwnerRepository owners) {
		this.weightRecords = weightRecords;
		this.owners = owners;
	}

	@PostMapping
	public ResponseEntity<WeightRecord> recordWeight(@PathVariable("ownerId") int ownerId,
			@PathVariable("petId") int petId, @Valid @RequestBody WeightRecord weightRecord) {

		Optional<Owner> optionalOwner = this.owners.findById(ownerId);
		if (optionalOwner.isEmpty()) {
			return ResponseEntity.notFound().build();
		}

		Owner owner = optionalOwner.get();
		Pet pet = owner.getPet(petId);

		if (pet == null) {
			return ResponseEntity.notFound().build();
		}

		weightRecord.setPetId(petId);
		WeightRecord saved = this.weightRecords.save(weightRecord);
		return ResponseEntity.status(HttpStatus.CREATED).body(saved);
	}

	@GetMapping("/history")
	public ResponseEntity<List<WeightRecord>> getWeightHistory(@PathVariable("ownerId") int ownerId,
			@PathVariable("petId") int petId) {

		Optional<Owner> optionalOwner = this.owners.findById(ownerId);
		if (optionalOwner.isEmpty()) {
			return ResponseEntity.notFound().build();
		}

		Owner owner = optionalOwner.get();
		Pet pet = owner.getPet(petId);

		if (pet == null) {
			return ResponseEntity.notFound().build();
		}

		List<WeightRecord> history = this.weightRecords.findByPetIdOrderByRecordDateDesc(petId);
		return ResponseEntity.ok(history);
	}

}

